(function(){
    const revertDelay = 1500;

    function setStatus(button,text){
        if(!button){return}
        const originalText = button.getAttribute('data-original-text');
        if(!originalText){
            button.setAttribute('data-original-text',button.textContent.trim())
        }
        button.textContent = text;
        button.disabled = true;
        setTimeout(()=>{
            button.textContent = button.getAttribute('data-original-text');
            button.disabled = false
        },revertDelay)
    }

    document.addEventListener('click',async function(event){
        const button = event.target.closest('[data-copy-identifier]');
        if(!button){return}

        const cardForm = button.closest('form');
        if(!cardForm){return}

        const identifierInput = cardForm.querySelector('input[name="identifier"]');
        if(!identifierInput){return}

        const identifier = identifierInput.value;
        if(!identifier){return}

        try{
            await navigator.clipboard.writeText(identifier);
            setStatus(button,'Copied!')
        }catch(err){
            console.warn('Failed to copy identifier',err);
            setStatus(button,'Failed')
        }
    })
})();

(function(){

    const BATCH_SIZE = 25;
    const MAX_CONCURRENT = 2;

    const queue = [];
    const requested = new Set();
    const costsById = new Map();

    let inFlight = 0;
    let flushTimer = null;

    const safeCurrency = (value)=>{
        const n = Number(value||0);
        if(!Number.isFinite(n)) return '$0.00';
        return `$${n.toFixed(2)}`
    };

    const costBadgeId = (identifier)=>
        `cost-badge-${String(identifier||'').replaceAll('.', '-')}`;

    const setTotal = ()=>{
        const el = document.getElementById('total-current-cost');
        if(!el) return;

        let total = 0;
        for(const value of costsById.values()){
            total += Number(value||0)
        }
        el.textContent = safeCurrency(total);
    };

    function updateTotalCount() {
        const container = document.getElementById("inventory");
        const totalEl = document.getElementById("total-resource-count");

        if (!container || !totalEl) return;

        const cards = container.querySelectorAll("form.card");
        totalEl.textContent = cards.length;
    }

    // ✅ SAFE SORT (cards only)
    function sortCardsByCost() {
        const container = document.getElementById("inventory");
        if (!container) return;

        const cards = Array.from(container.querySelectorAll("form.card"));

        cards.sort((a, b) => {
            const costA = parseFloat(a.dataset.cost || 0);
            const costB = parseFloat(b.dataset.cost || 0);
            return costB - costA;
        });

        cards.forEach(card => container.appendChild(card));
    }

    const paintBatch = (items)=>{
        (items || []).forEach((item)=>{
            const identifier = item && item.identifier;
            if(!identifier) return;

            const value = Number(item.current_cost || 0);
            const safeValue = Number.isFinite(value) ? value : 0;

            costsById.set(identifier, safeValue);

            const badge = document.getElementById(costBadgeId(identifier));
            if(badge){
                badge.textContent = safeCurrency(safeValue);

                const card = badge.closest("form.card");
                if(card){
                    card.dataset.cost = safeValue;
                }
            }
        });

        setTotal();
        updateTotalCount();

        // ✅ ONLY place where sorting happens
        if (costsById.size > 0) {
            sortCardsByCost();
        }
    };

    const flush = ()=>{
        while(inFlight < MAX_CONCURRENT && queue.length > 0){

            const identifiers = queue.splice(0,BATCH_SIZE);
            inFlight += 1;

            fetch('/costs/batch',{
                method:'POST',
                headers:{
                    'Content-Type':'application/json',
                    'X-Requested-With':'XMLHttpRequest'
                },
                credentials:'same-origin',
                body:JSON.stringify({identifiers})
            })
            .then((response)=>response.ok ? response.json() : {items:[]})
            .then((payload)=>paintBatch(payload.items || []))
            .catch(()=>{})
            .finally(()=>{
                inFlight -= 1;
                if(queue.length > 0){
                    flush()
                }
            })
        }
    };

    const scheduleFlush = ()=>{
        if(flushTimer) return;
        flushTimer = window.setTimeout(()=>{
            flushTimer = null;
            flush()
        },150);
    };

    const enqueueVisible = (reset)=>{
        const inventory = document.getElementById('inventory');
        if(!inventory) return;

        if(reset){
            queue.length = 0;
            requested.clear();
            costsById.clear();

            inventory.querySelectorAll("form.card").forEach(card=>{
                card.dataset.cost = 0;
            });

            inventory.querySelectorAll("[id^='cost-badge']").forEach(badge=>{
                badge.textContent = "$0.00";
            });

            setTotal();
        }

        const ids = Array.from(
            inventory.querySelectorAll("form.card")
        ).map(card=>{
            const input = card.querySelector("input[name='identifier']");
            return input?.value;
        }).filter(Boolean);

        ids.forEach((id)=>{
            if(requested.has(id)) return;
            requested.add(id);
            queue.push(id);
        });

        if(queue.length > 0){
            scheduleFlush();
        }
    };

    // 🔥 ONLY trigger cost loading (NOT sorting)
    document.body.addEventListener('htmx:afterSwap',function(event){
        if(!event || !event.target) return;

        if(event.target.id === 'inventory'){
            enqueueVisible(true);
            updateTotalCount();
        }
    });

})();
